// Extrai mensagem e telefone de diferentes provedores WhatsApp
// Suporta: Z-API, Evolution API, Chatwoot

const body = $input.item.json.body || $input.item.json;

let phone = '';
let message = '';
let providerName = '';

// Z-API
if (body.phone && body.text && body.text.message) {
  phone = body.phone;
  message = body.text.message;
  providerName = 'z-api';
}
// Evolution API
else if (body.data && body.data.key && body.data.message) {
  phone = body.data.key.remoteJid.replace('@s.whatsapp.net', '');
  message = body.data.message.conversation || 
            body.data.message.extendedTextMessage?.text || 
            '';
  providerName = 'evolution';
}
// Chatwoot
else if (body.conversation && body.content) {
  phone = body.conversation?.meta?.sender?.phone_number || '';
  message = body.content;
  providerName = 'chatwoot';
}
// Genérico (fallback)
else {
  phone = body.phone || body.from || '';
  message = body.message || body.text || body.content || '';
  providerName = 'generic';
}

if (!message) {
  throw new Error('Mensagem vazia — ignorando.');
}

return [{ json: { phone, message, providerName } }];

// Extrai o texto da resposta do Claude
const response = $input.item.json;
const text = response.content?.[0]?.text || '';

if (!text) {
  throw new Error('Claude não retornou texto.');
}

const phone = $('Extrai Mensagem').item.json.phone;
const provider = $('Extrai Mensagem').item.json.providerName;

return [{ json: { phone, resposta: text, provider } }];
